-- Weekly Arena 2026-11-02: 10 questions, all unseen.
insert into public.arenas(id,title,description,starts_at,ends_at,duration_minutes,status,questions)
values('a5504a1e-5594-4038-87fc-89548a19c042','Weekly Arena — 2026-11-02','A fresh weekly set of 10 problems across Algebra, Geometry, Combinatorics and Number Theory. Open for 7 days; 60 minutes once you begin.','2026-11-02T00:00:00.000Z','2026-11-09T00:00:00.000Z',60,'published','[{"id":"gen-aime-alg-002","title":"Reciprocal echoes","question":"A positive real $x$ satisfies $x+\\frac1x=5$. Find $x^2+\\frac1{x^2}$.","correctAnswer":"023","solution":"$(x+x^{-1})^2=x^2+2+x^{-2}=5^2$, so the answer is $23$.","hint":"Square the relation and remove the middle term.","topic":"Algebra","level":"Advanced","competition":"AIME","estimatedSteps":2,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":40,"difficulty":-0.8},{"id":"alg-o01","title":"Power Sums Without Solving","question":"A positive real number $x$ satisfies $x + \\frac{1}{x} = 3$. Find the last three digits of $\\left(x^5 + \\frac{1}{x^5}\\right)^2$.","correctAnswer":"129","solution":"With $T_0=2$ and $T_1=3$, the recurrence $T_n=3T_{n-1}-T_{n-2}$ gives $T_2=7$, $T_3=18$, $T_4=47$, and $T_5=123$. Thus $T_5^2=123^2=15129$, whose last three digits are $129$.","hint":"Let $T_n=x^n+x^{-n}$. The relation $x+x^{-1}=3$ gives $T_n=3T_{n-1}-T_{n-2}$.","topic":"Algebra","level":"Olympiad","competition":"AIME","estimatedSteps":5,"abstraction":5,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":79,"difficulty":0.76},{"id":"gen-amc-num-024","title":"Counting divisors by exponents","question":"How many positive divisors does $121500$ have?","correctAnswer":"72","solution":"$121500=2^{2}3^{5}5^{3}$, so the count is 72.","hint":"Factor the number and multiply one more than each exponent.","topic":"Number Theory","level":"Foundation","competition":"AMC","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":47,"difficulty":-0.52},{"id":"gen-aime-com-021","title":"Unordered triples","question":"How many subsets of size 3 can be selected from 12 labelled objects?","correctAnswer":"220","solution":"$\\binom{12}{3}=220$.","hint":"Divide ordered selections by $3!$.","topic":"Combinatorics","level":"Advanced","competition":"AIME","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04},{"id":"gen-amc-alg-001","title":"A symmetric pair","question":"Positive reals $a,b$ satisfy $a+b=5$ and $ab=4$. Find $a^2+b^2$.","correctAnswer":"17","solution":"$a^2+b^2=5^2-2(4)=17$.","hint":"Expand $(a+b)^2$ and isolate $a^2+b^2$.","topic":"Algebra","level":"Foundation","competition":"AMC","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04},{"id":"gen-aime-geo-014","title":"A regular hexagon","question":"A regular hexagon has side 12. Find its area divided by $\\sqrt3$.","correctAnswer":"216","solution":"$K=6(\\sqrt3/4)12^2$, so $K/\\sqrt3=216$.","hint":"Split the hexagon into six equilateral triangles.","topic":"Geometry","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":49,"difficulty":-0.44},{"id":"gen-aime-num-028","title":"The exponent returns","question":"Find $3^{1202}$ modulo 1000.","correctAnswer":"009","solution":"$3^{100}\\equiv1\\pmod{1000}$, so the remainder is $9$.","hint":"Use the period of 3 modulo 1000.","topic":"Number Theory","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":3,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":53,"difficulty":-0.28},{"id":"gen-amc-geo-008","title":"Heron, carefully","question":"A triangle has side lengths 13, 14, 15. Find its area.","correctAnswer":"84","solution":"Heron’s formula gives area 84.","hint":"Use Heron’s formula with the semiperimeter.","topic":"Geometry","level":"Foundation","competition":"AMC","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":49,"difficulty":-0.44},{"id":"gen-amc-num-028","title":"The exponent returns","question":"Find $3^{802}$ modulo 1000.","correctAnswer":"9","solution":"$3^{100}\\equiv1\\pmod{1000}$, so the remainder is $9$.","hint":"Use the period of 3 modulo 1000.","topic":"Number Theory","level":"Foundation","competition":"AMC","estimatedSteps":3,"abstraction":3,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":53,"difficulty":-0.28},{"id":"gen-aime-com-015","title":"Choose without order","question":"How many 2-person teams can be chosen from 9 distinct people?","correctAnswer":"036","solution":"$\\binom{9}{2}=36$.","hint":"Use a binomial coefficient.","topic":"Combinatorics","level":"Advanced","competition":"AIME","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04}]'::jsonb)
on conflict(id) do nothing;
